// Generates src/environments/environment.ts from .env (or process.env).
//
// The backend URL is kept out of git (public repo): the generated file is
// gitignored and rebuilt from local config on install/start/build/test.
import { writeFileSync, readFileSync, existsSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';

function loadDotEnv() {
  const env = {};
  const path = join(process.cwd(), '.env');
  if (!existsSync(path)) return env;
  for (const line of readFileSync(path, 'utf8').split(/\r?\n/)) {
    if (!line.trim() || line.trim().startsWith('#')) continue;
    const match = line.match(/^\s*([\w.-]+)\s*=\s*(.*)\s*$/);
    if (match) env[match[1]] = match[2].replace(/^["']|["']$/g, '');
  }
  return env;
}

const fileEnv = loadDotEnv();
const apiBaseUrl = process.env.API_BASE_URL ?? fileEnv.API_BASE_URL ?? '';
const production = process.env.NODE_ENV === 'production';

const out = join(process.cwd(), 'src', 'environments', 'environment.ts');
mkdirSync(dirname(out), { recursive: true });
writeFileSync(
  out,
  `// GENERATED by scripts/generate-environment.mjs — do not edit, do not commit.
// Values come from .env (see .env.example). Regenerate with \`npm run gen:env\`.
export const environment = {
  production: ${production},
  apiBaseUrl: ${JSON.stringify(apiBaseUrl)},
} as const;
`,
);

console.log(`[gen:env] wrote ${out} (apiBaseUrl=${apiBaseUrl || '<empty>'})`);
if (!apiBaseUrl) {
  console.warn('[gen:env] API_BASE_URL is empty — set it in .env for live API calls.');
}
